int alter = 15;
bool hatTicket = true;
bool istWochenende = false;
bool istFeiertag = true;

if (alter >= 14 && hatTicket)
{
    Console.WriteLine("Du darfst ins Konzert.");
}

if (istWochenende || istFeiertag)
{
    Console.WriteLine("Heute ist schulfrei!");
}

if (!hatTicket)
{
    Console.WriteLine("Du brauchst noch ein Ticket.");
}
// Ausgabe:
// Du darfst ins Konzert.
// Heute ist schulfrei!

